10	// V2: Staff-only gate. Checks supabase_uid maps to a SidestStaff record.
11	// Accepts optional role parameters: middleware('staff:admin') restricts to a specific role,
12	// middleware('staff') allows any authenticated staff.
13	class EnsureSidestStaff
14	{
15	    public function handle(Request $request, Closure $next, string ...$roles): Response
16	    {
17	        // Set by VerifySupabaseJwt middleware
18	        $uid = $request->attributes->get('supabase_uid');
19	
20	        if (! $uid) {
21	            return response()->json(['message' => 'Unauthenticated'], 401);
22	        }
23	
24	        $staff = $request->attributes->get('sidest_staff')
25	            ?? SidestStaff::query()->where('auth_user_id', $uid)->first();
26	
27	        if (! $staff) {
28	            return response()->json(['message' => 'Staff access required'], 403);
29	        }
30	
31	        if (! empty($roles) && ! in_array($staff->role, $roles, true)) {
32	            return response()->json(['message' => 'Insufficient staff role'], 403);
33	        }
34	
35	        // Attach for controllers to use
36	        $request->attributes->set('sidest_staff', $staff);
37	
38	        return $next($request);
39	    }
40	}
